PROMPT_SET = [
 ("Design","Minimum viable set: 30 prompts per vertical x 3 engines (ChatGPT, Google AI Mode/AIO, Perplexity), plus Gemini, Claude and Copilot where relevant; sampled weekly with 3 runs per prompt."),
 ("Themes","Group prompts into themes: category definition, 'best X for Y', 'X vs Y', pricing/cost, how-to, troubleshooting, 'is X worth it', local/near me, brand facts ('what is <brand>')."),
 ("Variants","Write 3-5 natural-language variants per theme (23-word average prompts, personas, constraints) to absorb prompt fragility."),
 ("Sources of prompts","Sales call questions, support tickets, People Also Ask, Reddit threads, ChatGPT follow-up suggestions, GSC question queries, AI tool 'related prompts'."),
 ("Collection","OpenAI Responses API with web_search (record sources list), Perplexity Sonar (search_results), Gemini grounding (groundingChunks), Claude web search; consumer-app spot checks monthly for 10 prompts."),
 ("Labelling","LLM judge extracts: brand mentioned (y/n), owned URL cited (y/n), position, sentiment, competitor set; 5% human audit; agreement >=90%."),
 ("Variance","Report min/median/max across runs; alert only on theme-level change >20% sustained 2 weeks; annotate engine updates and Google spam/core updates."),
 ("Memory vs search","Tag citations as 'memory' (no live source) or 'search' (live URL); memory gaps need PR/entity work, search gaps need technical/content fixes."),
 ("Competitor set","Fix 3-5 competitors per theme; compute share of voice = brand mentions / total brand mentions in set."),
 ("Compliance","Respect API terms (Gemini grounding ToS limits competitive tracking); never scrape consumer apps; store raw answers for audit."),
]
EXEC_SUMMARY = [
 ("1","No Google core update has run since May 2026 (as of 27 Oct 2026); two spam updates (Aug 18-21, Sep 24-Oct 8) enforced existing scaled-content, site-reputation and expired-domain policies. Unedited AI/programmatic sites lost 40-95%; human-edited AI content at moderate velocity gained 30-80%.","S05,S06,S43,S62"),
 ("2","Google's Oct 1 2026 guidance makes manual fact-checking of all AI output, including metadata, the explicit expectation, and calls fabricated authors deceptive. Treat human review as a HARD_BLOCK gate in every agent workflow.","S01,S63"),
 ("3","The strongest correlates of AI visibility are third-party brand mentions (r=0.66), YouTube mentions (r=0.74), original statistics and cited sources (+30-40% in the only peer-reviewed study), freshness (cited pages 26% fresher) and answer-first passage structure (44% of citations from first 30% of page).","S09,S13,S16,S12"),
 ("4","Debunked levers: llms.txt (Google does not use it; no correlation), schema markup for citations (no effect in 1,885-page study), AI-specific rewrites, self-ranked listicles.","S04,S08,S10,S11,S30"),
 ("5","Crawler policy is the cheapest win and the costliest mistake: allow OAI-SearchBot, Claude-SearchBot, PerplexityBot and user fetchers; serve server-rendered HTML; decide training bots separately; verify at the CDN edge.","S23,S24,S25,S26,S27"),
 ("6","Engines diverge: ChatGPT shifted to primary sources and cut Reddit in Aug 2026; Google AIO still favours YouTube/Reddit; engines disagree on brands 62% of the time. Track themed prompt sets per engine, not single prompts.","S36,S37,S38,S19"),
 ("7","Measurement changed: GSC generative-AI report (June 2026), GA4 AI Assistant channel (May 2026), Bing AI Performance (Feb/June 2026), but ChatGPT dropped referrer tagging in Oct 2026, so AI referrals are undercounted.","S47,S48,S49,S66"),
 ("8","Highest-probability strategies: crawler access + SSR (90%), measurement program (85%), content refresh (75%), information gain (70%), answer-first structure (70%). Highest risk: programmatic scale (40% win, high penalty risk) and Wikipedia (35%).","S09,S13,S16"),
 ("9","Agentic execution works when agents research, draft, check and queue, while humans approve and post. Velocity governors (default 10 blog / 25 programmatic pages per week), claim ledgers, information-gain scoring and edge-level bot tests are the core controls.","S43,S44,S01"),
 ("10","Tool stack: Semrush/Ahrefs MCP + GSC MCP + Screaming Frog v24 MCP under Claude Code for execution; Profound/Peec/Otterly or suite add-ons for AI visibility; official OpenAI, Perplexity, Gemini and Claude APIs for reproducible sampling; Bing AI Performance as the only native citation report.","S39,S40,S41,S45"),
]
README = [
 ("Purpose","Evidence-graded playbook for SEO and AEO/GEO executed through AI agents, covering practice from August 2026 to October 27 2026."),
 ("How to read","Start with Executive Summary, then Strategy Playbook (what and how likely), Agent Execution (how an agent runs it), Validation Checklist (how to prove it), Penalty Safeguards and Anti-patterns (what not to do), Tools sheets, Measurement, Prompt Set Design, Timeline, Sources."),
 ("Evidence grades","A = official documentation, primary data or peer-reviewed study. B = large industry dataset study (Ahrefs, Semrush, SE Ranking, Seer, Peec) or trade-press reporting of official news. C = vendor or agency report, practitioner write-up. D = single unverified claim (kept because it is widely repeated; verify before relying)."),
 ("Win probability","Estimated probability that a competent team executing the strategy for 90-180 days on a site with sound fundamentals sees a measurable positive change in the primary KPI. Calibrated to evidence grade and effect sizes; expert judgment, not a measured frequency. Edit the blue cells in Strategy Playbook to re-score."),
 ("Priority score","Formula in Strategy Playbook: win probability x impact x (4 - penalty risk) / effort. Higher is better. Recalculates when inputs change."),
 ("Verdict vocabulary","PASS / FAIL / UNKNOWN / NEEDS_REVIEW and HARD_BLOCK / REVIEW_REQUIRED / ADVISORY are reused from the Palgu completeness framework (S72); control IDs AC-C039..AC-C062 cross-reference that workbook."),
 ("Research method","Web search (extended) plus Gemini 3.1 Pro grounded search on 8 question sets, cross-checked against official Google, Bing, OpenAI, Anthropic and Perplexity documentation. Where only secondary write-ups were reachable, the source row says so."),
 ("Known limitations","Many 2026 numbers come from vendors with commercial interest and conflict with each other; AI engine behaviour changes monthly; API answers differ from consumer apps; some Gemini-grounded claims (Atlas shutdown, Reddit 86% collapse, ChatGPT UTM drop, deutschwunder case) are graded D and should be verified before reuse."),
 ("Prepared","2026-10-27 for ali.shaheen@edubites.com. No API keys are stored in this workbook."),
]
